import { Pool } from 'pg';
import { Connection, Keypair, PublicKey } from '@solana/web3.js';
import { createMint, getOrCreateAssociatedTokenAccount, mintTo, transfer } from '@solana/spl-token';

function text(v){return String(v??'').trim();}
function secret(value){const raw=text(value);if(!raw)throw new Error('SOLANA_PAYER_SECRET_KEY is required.');const bytes=raw.startsWith('[')?Uint8Array.from(JSON.parse(raw)):Uint8Array.from(Buffer.from(raw,'base64'));return bytes.length===32?Keypair.fromSeed(bytes):Keypair.fromSecretKey(bytes);}
function positive(v,name){const n=Number(v);if(!Number.isFinite(n)||n<=0)throw new Error(`${name} must be greater than zero.`);return n;}
function units(value,decimals){const s=String(value);if(!/^\d+(?:\.\d+)?$/.test(s))throw new Error('Invalid token quantity.');const [w,f='']=s.split('.');if(f.length>decimals)throw new Error(`SRA quantity exceeds ${decimals} decimals.`);return BigInt(`${w}${f.padEnd(decimals,'0')}`);}

export class SraTokenWorker {
  constructor(env=process.env){this.env=env;this.rpc=text(env.SOLANA_RPC_URL);this.db=text(env.DATABASE_URL||env.EXECUTOR_DATABASE_URL);this.pool=this.db?new Pool({connectionString:this.db}):null;this.payer=null;this.connection=null;}
  async initialize(){if(!this.rpc||!this.pool)throw new Error('Solana RPC and executor database are required.');this.payer=secret(this.env.SOLANA_PAYER_SECRET_KEY);this.connection=new Connection(this.rpc,'confirmed');await this.pool.query(`CREATE TABLE IF NOT EXISTS sra_token_chain_state (symbol TEXT PRIMARY KEY, mint_address TEXT NOT NULL, decimals INTEGER NOT NULL, authorized_supply NUMERIC NOT NULL, issued_supply NUMERIC NOT NULL, platform_token_account TEXT NOT NULL, mint_signature TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);await this.pool.query(`CREATE TABLE IF NOT EXISTS sra_token_transfers (transfer_id TEXT PRIMARY KEY, destination_address TEXT NOT NULL, amount NUMERIC NOT NULL, transaction_signature TEXT, state TEXT NOT NULL, response_json JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);}
  async state(){return (await this.pool.query(`SELECT * FROM sra_token_chain_state WHERE symbol='SRA'`)).rows[0]||null;}
  async createSraMint(input,idempotencyKey){const issuanceId=text(input.issuanceId);if(!issuanceId||issuanceId!==idempotencyKey)throw new Error('Idempotency-Key must equal issuanceId.');const authorizedSupply=positive(input.authorizedSupply,'authorizedSupply');const decimals=Number.isInteger(input.decimals)?input.decimals:8;if(decimals<0||decimals>9)throw new Error('decimals must be between 0 and 9.');const existing=await this.state();if(existing){if(Number(existing.authorized_supply)!==authorizedSupply)throw new Error('SRA mint already exists with a different authorized supply.');return {symbol:'SRA',mintAddress:existing.mint_address,platformTokenAccount:existing.platform_token_account,authorizedSupply:Number(existing.authorized_supply),issuedSupply:Number(existing.issued_supply),decimals:existing.decimals,state:'ACTIVE',existing:true};}
    const mint=await createMint(this.connection,this.payer,this.payer.publicKey,this.payer.publicKey,decimals);const account=await getOrCreateAssociatedTokenAccount(this.connection,this.payer,mint,this.payer.publicKey);const raw=units(authorizedSupply,decimals);const signature=await mintTo(this.connection,this.payer,mint,account.address,this.payer,raw);await this.pool.query(`INSERT INTO sra_token_chain_state(symbol,mint_address,decimals,authorized_supply,issued_supply,platform_token_account,mint_signature) VALUES('SRA',$1,$2,$3,$3,$4,$5)`,[mint.toBase58(),decimals,authorizedSupply,account.address.toBase58(),signature]);return {symbol:'SRA',mintAddress:mint.toBase58(),platformTokenAccount:account.address.toBase58(),authorizedSupply,issuedSupply:authorizedSupply,decimals,transactionSignature:signature,state:'ACTIVE',existing:false};}
  async transferSra(input,idempotencyKey){const transferId=text(input.transferId);if(!transferId||transferId!==idempotencyKey)throw new Error('Idempotency-Key must equal transferId.');const amount=positive(input.amount,'amount');const destinationAddress=text(input.destinationAddress);let owner;try{owner=new PublicKey(destinationAddress);}catch{throw new Error('destinationAddress is not a valid Solana address.');}const old=(await this.pool.query('SELECT response_json FROM sra_token_transfers WHERE transfer_id=$1',[transferId])).rows[0];if(old?.response_json)return old.response_json;const state=await this.state();if(!state)throw new Error('SRA has not been put on chain yet.');const mint=new PublicKey(state.mint_address);const source=new PublicKey(state.platform_token_account);const destination=await getOrCreateAssociatedTokenAccount(this.connection,this.payer,mint,owner);const signature=await transfer(this.connection,this.payer,source,destination.address,this.payer,units(amount,state.decimals));const response={transferId,symbol:'SRA',mintAddress:state.mint_address,fromAddress:this.payer.publicKey.toBase58(),destinationAddress,amount,transactionSignature:signature,state:'CONFIRMED',confirmedAt:new Date().toISOString()};await this.pool.query(`INSERT INTO sra_token_transfers(transfer_id,destination_address,amount,transaction_signature,state,response_json) VALUES($1,$2,$3,$4,'CONFIRMED',$5)`,[transferId,destinationAddress,amount,signature,response]);return response;}
  async close(){await this.pool?.end();}
}
